\label{generalised2}
An algebra $\langle T,\wedge,\vee,\rightarrow,\sim,0,1 \rangle$ of type $(2,2,2,1,0,0)$ is called a 
\textit{Nelson algebra} if $\langle T,\wedge,\vee,\sim,0,1 \rangle$ is a Kleene algebra and 
for every $x,y,z\in T$ the following equations are satisfied:
\begin{enumerate}[\normalfont Ne4)]
\item $x\rightarrow x = 1$,
\end{enumerate}
\begin{enumerate}[\normalfont Ne5)]
\item $x\rightarrow (y\rightarrow z) = (x\wedge y)\rightarrow z$,
\end{enumerate}
\begin{enumerate}[\normalfont Ne6)]
\item $x\wedge (x\rightarrow y) = x \wedge (\sim x \vee y)$,
\end{enumerate}
\begin{enumerate}[\normalfont Ne7)]
\item $\sim x\vee y \leq x\rightarrow y $, 
\end{enumerate}
\begin{enumerate}[\normalfont Ne8)]
\item $x\rightarrow (y\wedge z) = (x\rightarrow y)\wedge (x\rightarrow z)$.
\end{enumerate}

\label{example1}
	The set $A=\lbrace 0,a,1\rbrace$ where the elements are totally ordered $0<a<1$ and the operation $\rightarrow$ is defined by
	\begin{center}
	\begin{tabular}{|c|c|c|c|}
		\hline
		$\rightarrow$& $0$ & $a$ & $1$ \\
		\hline
		$0$ & $1$ & $a$ & $1$ \\
		\hline
		$a$ & $0$ & $1$ & $0$ \\
		\hline
		$1$ & $0$ & $a$ & $1$ \\
		\hline
	\end{tabular}
	\end{center}
	is an h-lattice.

\label{generalised}
An algebra $\langle T, \wedge, \vee, \rightarrow, \sim, 0, 1\rangle$ of type $(2, 2, 2, 1, 0, 0)$ is said to be a
\textit{hemi-Nelson algebra} (h-Nelson algebra for short) 
if $\langle T, \wedge, \vee, \sim, 0, 1\rangle$ is a Kleene algebra and the
following conditions are satisfied for every $x,y,z\in T$:
\begin{enumerate} [\normalfont (hN1)]
\item $x\rightarrow x=1$, \label{e1}
\item $x\wedge (x\rightarrow y)\leq x\wedge (\sim x\vee y)$, \label{e2}
\item $\sim(x\rightarrow y)\rightarrow (x\wedge \sim y)=1$, \label{e3}
\item $(x\wedge \sim y)\rightarrow \sim(x\rightarrow y)=1$, \label{e4}
\item $(x\wedge y \wedge (x\rightarrow y)) \rightarrow (x \wedge (x\rightarrow y)) = 1$, \label{e5}
\item $(x\wedge (x\rightarrow y)) \rightarrow (x\wedge y \wedge (x\rightarrow y)) = 1$, \label{e6}

\item if $x\rightarrow y = 1$, $y\rightarrow x = 1$, $y\rightarrow z = 1$ and $z\rightarrow y = 1$ then $x\rightarrow z = 1$ and $z\rightarrow x = 1$, \label{trans}
\item if $x\rightarrow y = 1$ and $y\rightarrow x = 1$ then $(x\wedge z)\rightarrow (y\wedge z) = 1$,\label{infimo}
\item if $x\rightarrow y = 1$ and $y\rightarrow x = 1$ then $(x\vee z)\rightarrow (y\vee z) = 1$,\label{supremo}
\item if $x\rightarrow y = 1$ and $y\rightarrow x = 1$ then $(x\rightarrow z) \rightarrow (y\rightarrow z) = 1$ and $(z\rightarrow x) \rightarrow (z\rightarrow y) = 1$. \label{implic}
\end{enumerate}

\label{example2}
Considering the h-lattice given in Example \ref{example1} 
we have that $\mathrm{K}(A)$ is endowed by a structure of h-Nelson algebra, 
where its universe is the chain of five elements given by $(0,1)<(0,a)<(0,0)<(a,0)<(1,0)$.

\label{eq neg}
    Let $T\in \mathsf{KhIL}$. Then, the following condition is satisfied for all $x,y,z\in T$:
    \begin{equation}\label{eq n}
        (x\rightarrow y)\vee (z\wedge\sim z)=(x\vee (z\wedge \sim z))\rightarrow (y\vee (z\wedge \sim z)).
    \end{equation}

\label{kleene cond}
    Let $T$ be a Kleene algebra. Then,
    \[1=x\vee (z\wedge\sim z) \text{ if and only if }x=1.\]

\label{equivalence eq}
    If $T$ be a Kleene algebra satisfying Conditions from (hN1) to (hN6) and equation (\ref{eq n}), the following conditions are equivalent:
    \begin{enumerate}
        \item $x\rightarrow y=1$ and $y\rightarrow x=1$;
        \item There exists $z\in T$ such that $x\vee (z\wedge\sim z)=y\vee (z\wedge\sim z)$.
    \end{enumerate}

\label{lc3}
Let $T\in \mathsf{KhIL}$, $\theta \in \mathrm{Con}(T)$ and $x,y \in T$. Then $(x,y)\in \theta$ if and only if
$x\rightarrow y$, $\sim y \rightarrow \sim x$, $y\rightarrow x$, $\sim x \rightarrow \sim y \in 1/\theta$.

\label{lc4}
Let $T\in \mathsf{KhIL}$ and $\theta,\psi \in \mathrm{Con}(T)$. Then $\theta\subseteq \psi$ if and only if
$1/\theta \subseteq 1/\psi$. In particular, $\theta = \psi$ if and only if $1/\theta = 1/\psi$.

\label{lc5}
Let $T\in \mathsf{KhIL}$ and $F$ an implicative filter of $T$ which satisfies
F1) and F2) of Definition \ref{gf}
for every $x,y\in T$ and $f\in F$. Then $F$ is a filter. Moreover, $x\in F$
if and only if $1\rightarrow x\in F$.

\label{thm-con}
Let $T\in \mathsf{KhIL}$. The assignments $\theta \mapsto 1/\theta$ and $F\mapsto \Theta(F)$ establish an
order isomorphism between $\mathrm{Con}(T)$ and $\mathrm{hIF}(T)$.

\label{ce2}
Let $T\in \mathsf{KhIL}^{c}$.
Then $\rho$ is surjective if and only if $T$ satisfies the condition $\mathsf{(C)}$.

\label{alpha}
Let $A\in \mathsf{hIL}$. Then the map $\alpha_{A}:A \rightarrow \mathsf{C}(\mathrm{K}(A))$ given by $\alpha_{A}(a) = (a,a\rightarrow 0)/\theta$
is an isomorphism.

\label{center}
There exists a categorical equivalence between $\mathsf{hIL}$ and the full subcategory of $\mathsf{KhIL}^{c}$
whose objects satisfy $\mathsf{(CK)}$.

An algebra $\langle T, \wedge, \vee, \to, \sim, 1\rangle$ of type $(2,2,2,1,0)$
is a \textit{semi-Nelson algebra} if for every $x,y,z \in H$ the
following conditions are satisfied:
\begin{enumerate}[{\rm (SN1)}]
 \item $x \wedge (x \vee y)  =  x$, \label{identidad_absorc}
 \item $x \wedge (y \vee z)  =  (z \wedge x) \vee (y \wedge x)$, \label{identidad_distrib_inf}
 \item $\sim \sim x  =  x$, \label{identidad_doble_neg}
 \item $\sim (x \wedge y)  =  \sim x \vee \sim y$, \label{identidad_ditrib_neg}
 \item $x \wedge \sim x  =  (x \wedge \sim x) \wedge (y \vee \sim y)$, \label{identidad_kleene}
 \item $x \wedge (x \to_N  y)  =  x \wedge (\sim x \vee y)$, \label{identidad_implic_negacion}
 \item $x \to_N  (y \to_N  z)  = (x \wedge y) \to_N  z$, \label{identidad_implica_infimo}
 \item $(x \to_N  y) \to_N  [(y \to_N  x) \to_N  [(x \to  z) \to_N  (y \to  z)]]  =  1$, \label{identidad_congr_derecha}
 \item $(x \to_N  y) \to_N  [(y \to_N  x) \to_N  [(z \to  x) \to_N  (z \to  y)]]  =  1$, \label{identidad_congr_izquierda}
 \item $(\sim (x \to  y)) \to_N  (x \wedge \sim y)  =  1$, \label{identidad_negacion_implica_inf1}
 \item $(x \wedge \sim y) \to_N  (\sim (x \to  y))  =  1$. \label{identidad_negacion_implica_inf2}
\end{enumerate}
where, again, $x \to_N  y$ stands for the term $x \to (x \wedge y)$.

An algebra $\langle T, \wedge, \vee, \rightarrow, \sim, 0, 1\rangle$ of type $(2, 2, 2, 1, 0, 0)$ is said to be a
\textit{subresiduated Nelson algebra} if $\langle T, \wedge, \vee, \sim, 0, 1\rangle$ is a Kleene algebra and the
following conditions are satisfied for every $a,b,c\in T$:
\begin{enumerate}[\normalfont 1)]
\item $(x\vee y)\rightarrow z = (x\rightarrow z)\wedge (y\rightarrow z)$,
\item $z\rightarrow (x\wedge y) = (z\rightarrow x)\wedge (z\rightarrow y)$,
\item $((x\rightarrow y)\wedge (y\rightarrow z))\rightarrow (x\rightarrow z)=1$, 
\item $x\rightarrow x=1$, \label{imp1}
\item $x\wedge (x\rightarrow y)\leq x\wedge (\sim x\vee y)$, \label{inf}
\item $x\rightarrow y\leq z\rightarrow (x\rightarrow y)$, \label{impl2}
\item $\sim(x\rightarrow y)\rightarrow (x\wedge \sim y)=1$, \label{au}
\item $(x\wedge \sim y)\rightarrow \sim(x\rightarrow y)=1$. \label{ultima}
\end{enumerate}
